import React, { useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';

export default function {{component_name}}() {
  const goal = {{goal_cups}};
  const [cups, setCups] = useState(0);
  return (
    <View style={styles.box}>
      <Text style={styles.title}>Water Intake</Text>
      <View style={styles.row}>
        {Array.from({ length: goal }).map((_, i) => (
          <TouchableOpacity key={i} onPress={() => setCups(i + 1)}>
            <Text style={[styles.cup, i < cups && styles.full]}>💧</Text>
          </TouchableOpacity>
        ))}
      </View>
      <Text style={styles.count}>{cups} / {goal} cups</Text>
      <TouchableOpacity onPress={() => setCups(0)}><Text style={styles.reset}>Reset</Text></TouchableOpacity>
    </View>
  );
}
const styles = StyleSheet.create({
  box: { padding: 20, alignItems: 'center' },
  title: { fontSize: 18, fontWeight: '600', marginBottom: 12 },
  row: { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center' },
  cup: { fontSize: 32, opacity: 0.25, margin: 4 },
  full: { opacity: 1 },
  count: { marginTop: 12, fontSize: 16 },
  reset: { marginTop: 8, color: '#3b82f6' }
});
